package aurelia;
import com.sun.net.httpserver.*;
import java.net.*;import java.nio.charset.StandardCharsets;import java.time.LocalDate;import java.util.*;import java.util.concurrent.Executors;
/** Dependency-free Java 17 REST API. Demo data is held in memory and resets on restart. */
public final class LibraryServer{
 static final Service db=new Service();
 public static void main(String[]a)throws Exception{int port=Integer.parseInt(System.getenv().getOrDefault("PORT","8080"));HttpServer s=HttpServer.create(new InetSocketAddress(port),0);s.createContext("/api/health",x->send(x,200,"{\"status\":\"ok\",\"service\":\"aurelia\"}"));s.createContext("/api/books",x->send(x,200,db.books()));s.createContext("/api/loans",LibraryServer::loanRoute);s.createContext("/api/requests",LibraryServer::requestRoute);s.setExecutor(Executors.newCachedThreadPool());s.start();System.out.println("AURELIA API on http://localhost:"+port);}
 static void loanRoute(HttpExchange x)throws java.io.IOException{String p=x.getRequestURI().getPath(),m=x.getRequestMethod();if(m.equals("GET")){send(x,200,db.loans());return;}if(m.equals("POST")){Map<String,String>b=form(x);String r=db.borrow(b.get("bookId"));send(x,r.startsWith("{\"error")?409:201,r);return;}if(m.equals("DELETE")&&p.matches("/api/loans/[^/]+")){String r=db.giveBack(p.substring(p.lastIndexOf('/')+1));send(x,r.startsWith("{\"error")?404:200,r);return;}send(x,405,"{\"error\":\"Method not allowed\"}");}
 static void requestRoute(HttpExchange x)throws java.io.IOException{if(x.getRequestMethod().equals("GET")){send(x,200,db.requests());return;}if(x.getRequestMethod().equals("POST")){Map<String,String>b=form(x);if(b.getOrDefault("title","").isBlank()||b.getOrDefault("author","").isBlank()){send(x,400,"{\"error\":\"Title and author required\"}");return;}send(x,201,db.request(b.get("title"),b.get("author")));return;}send(x,405,"{\"error\":\"Method not allowed\"}");}
 static Map<String,String>form(HttpExchange x)throws java.io.IOException{Map<String,String>m=new HashMap<>();for(String z:new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8).split("&")){String[]p=z.split("=",2);if(p.length==2)m.put(URLDecoder.decode(p[0],StandardCharsets.UTF_8),URLDecoder.decode(p[1],StandardCharsets.UTF_8));}return m;}
 static void send(HttpExchange x,int code,String body)throws java.io.IOException{byte[]b=body.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");x.getResponseHeaders().set("Access-Control-Allow-Origin","*");x.getResponseHeaders().set("Access-Control-Allow-Methods","GET,POST,DELETE,OPTIONS");x.getResponseHeaders().set("Access-Control-Allow-Headers","Content-Type");if(x.getRequestMethod().equals("OPTIONS")){x.sendResponseHeaders(204,-1);return;}x.sendResponseHeaders(code,b.length);x.getResponseBody().write(b);x.close();}
 static String q(String s){return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n")+"\"";}
 static final class Service{
 LinkedHashMap<String,Book>books=new LinkedHashMap<>();LinkedHashMap<String,Loan>loans=new LinkedHashMap<>();List<String[]>requests=new ArrayList<>();
 Service(){add("B001","The Alchemist","Paulo Coelho","Fiction",3);add("B002","Atomic Habits","James Clear","Self Development",2);add("B003","Wings of Fire","A. P. J. Abdul Kalam","Biography",3);add("B004","The Great Gatsby","F. Scott Fitzgerald","Classic",2);add("B005","1984","George Orwell","Fiction",2);add("B006","Sapiens","Yuval Noah Harari","History",2);}
 void add(String id,String t,String a,String c,int n){books.put(id,new Book(id,t,a,c,n));}
 synchronized String books(){List<String>v=new ArrayList<>();for(Book b:books.values())v.add("{\"id\":"+q(b.id)+",\"title\":"+q(b.title)+",\"author\":"+q(b.author)+",\"category\":"+q(b.category)+",\"total\":"+b.total+",\"available\":"+b.available+"}");return "["+String.join(",",v)+"]";}
 synchronized String loans(){List<String>v=new ArrayList<>();for(Loan l:loans.values())if(!l.returned)v.add("{\"id\":"+q(l.id)+",\"bookId\":"+q(l.bookId)+",\"borrowed\":"+q(l.borrowed.toString())+",\"due\":"+q(l.due.toString())+"}");return "["+String.join(",",v)+"]";}
 synchronized String borrow(String id){Book b=books.get(id);if(b==null)return "{\"error\":\"Unknown book\"}";if(b.available<1)return "{\"error\":\"No copies available\"}";b.available--;String idLoan="L"+UUID.randomUUID().toString().substring(0,8);Loan l=new Loan(idLoan,id,LocalDate.now(),LocalDate.now().plusDays(14));loans.put(idLoan,l);return "{\"id\":"+q(idLoan)+",\"bookId\":"+q(id)+",\"due\":"+q(l.due.toString())+"}";}
 synchronized String giveBack(String id){Loan l=loans.get(id);if(l==null||l.returned)return "{\"error\":\"Active loan not found\"}";l.returned=true;books.get(l.bookId).available++;return "{\"returned\":true,\"loanId\":"+q(id)+"}";}
 synchronized String request(String t,String a){String id="R"+UUID.randomUUID().toString().substring(0,8);requests.add(new String[]{id,t,a,LocalDate.now().toString()});return "{\"id\":"+q(id)+",\"title\":"+q(t)+",\"author\":"+q(a)+",\"status\":\"Under review\"}";}
 synchronized String requests(){List<String>v=new ArrayList<>();for(String[]r:requests)v.add("{\"id\":"+q(r[0])+",\"title\":"+q(r[1])+",\"author\":"+q(r[2])+",\"created\":"+q(r[3])+",\"status\":\"Under review\"}");return "["+String.join(",",v)+"]";}
 }
 static final class Book{final String id,title,author,category;final int total;int available;Book(String i,String t,String a,String c,int n){id=i;title=t;author=a;category=c;total=n;available=n;}}
 static final class Loan{final String id,bookId;final LocalDate borrowed,due;boolean returned;Loan(String i,String b,LocalDate d,LocalDate due){id=i;bookId=b;borrowed=d;this.due=due;}}
}